function bindDevelopment(d){
  const q=document.getElementById('development-search'),count=document.getElementById('development-count');
  if(!q||!count)return;
  const rows=[...document.querySelectorAll('[data-development-row]')];
  const draw=()=>{const s=q.value.trim().toLowerCase();let visible=0;rows.forEach(r=>{const show=!s||(r.dataset.search||'').includes(s);r.hidden=!show;if(show)visible++});count.textContent=`${visible} of ${d.ipAssets.length} IP assets`;};
  q.addEventListener('input',draw);draw();
}
